@startuml
class Ingredient {
  +name : string
  +measuringUnit : string
  +quantityInStock : float
}

class Dish {
  +name : string
  +identifier : int
}

class DishIngredient {
  +quantity : float
}

class Table {
  +identifier : int
  +maximumAmountOfPeople : int
}

class Meal {
  +date : date
  +startTime : time
  +endTime : time
}

class MealDish {
  +quantity : int
}

class Waiter {
  +identifier : int
  +name : string
  +address : string
  +phoneNumber : string
}

class Client {
  +taxIdentificationNumber : string
  +name : string
  +address : string
}

Dish "1" *-- "1..*" DishIngredient : composed of
Ingredient "1" -- "1..*" DishIngredient : used in
Dish "1" -- "*" MealDish : consumed in
Meal "1" -- "1..*" MealDish : contains
Meal "1" --> "1" Table : takes place at
Meal "*" --> "0..1" Waiter : is served by
Meal "0..1" --> "0..1" Client : consumed by
@enduml

